import 'package:flutter/material.dart'; import '../models/chatbot_models.dart';
class ConversationListItem extends StatelessWidget { const ConversationListItem({super.key, required this.conversation, required this.selected, required this.onOpen, required this.onRename, required this.onDelete}); final ConversationSummary conversation; final bool selected; final VoidCallback onOpen, onRename, onDelete;
@override Widget build(BuildContext context) => ListTile(key: ValueKey('conversation-${conversation.id}'), selected: selected, title: Text(conversation.title?.trim().isNotEmpty == true ? conversation.title! : 'Conversation'), subtitle: conversation.messageCount == null ? null : Text('${conversation.messageCount} messages'), onTap: onOpen, trailing: PopupMenuButton<String>(onSelected: (value) { if (value == 'rename') onRename(); if (value == 'delete') onDelete(); }, itemBuilder: (_) => const [PopupMenuItem(value: 'rename', child: Text('Rename')), PopupMenuItem(value: 'delete', child: Text('Delete'))])); }
